import { validateInvoice } from "@sweberdev/summand"

export async function POST(req: Request) {
  const bytes = new Uint8Array(await req.arrayBuffer()) // XML or ZUGFeRD PDF
  const result = validateInvoice(bytes)

  if (!result.valid) {
    return Response.json({ errors: result.errors }, { status: 422 })
  }
  return Response.json({ profile: result.profile?.label, invoice: result.summary })
}
